            ],
            "signature": "edu_assign_preschool_teacher(uuid,uuid,uuid,uuid,uuid,uuid,uuid,text,text,date,date)",
            "definition": "CREATE OR REPLACE FUNCTION public.edu_assign_preschool_teacher(p_tenant_id uuid, p_actor_id uuid, p_branch_id uuid, p_operation_key uuid, p_course_id uuid, p_confirmation_id uuid, p_teacher_party_id uuid, p_role text, p_academic_year text, p_effective_start_date date, p_effective_end_date date)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\n SET statement_timeout TO '10s'\n SET lock_timeout TO '2s'\nAS $function$\nDECLARE v_row public.teacher_assignments%ROWTYPE; v_confirmation public.preschool_teacher_branch_confirmations%ROWTYPE;\nBEGIN\n  PERFORM public.preschool_teacher_assert_admin(p_tenant_id,p_actor_id,p_branch_id,p_course_id);\n  IF p_operation_key IS NULL OR p_course_id IS NULL OR p_confirmation_id IS NULL OR p_teacher_party_id IS NULL\n    OR p_role IS NULL OR p_role NOT IN('lead_teacher','co_teacher','assistant','substitute')\n    OR p_academic_year IS NULL OR length(p_academic_year) NOT BETWEEN 1 AND 80\n    OR p_academic_year<>btrim(p_academic_year) OR p_academic_year ~ '[[:cntrl:]]'\n    OR p_effective_start_date IS NULL OR NOT isfinite(p_effective_start_date)\n    OR (p_effective_end_date IS NOT NULL AND (NOT isfinite(p_effective_end_date) OR p_effective_end_date<p_effective_start_date))\n  THEN RAISE EXCEPTION 'PRESCHOOL_TEACHER_INVALID_REQUEST' USING ERRCODE='22023'; END IF;\n  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('preschool-teacher-assign:'||p_operation_key::text,0));\n  PERFORM public.preschool_teacher_assert_admin(p_tenant_id,p_actor_id,p_branch_id,p_course_id);\n  -- Recover an exact prior active operation before applying creation-only eligibility.\n  -- Revocation, Party soft deletion or course archival cannot erase prior success.\n  SELECT * INTO v_row FROM public.teacher_assignments\n    WHERE assignment_id=p_operation_key AND tenant_id=p_tenant_id FOR UPDATE;\n  IF FOUND THEN\n    IF v_row.tenant_id<>p_tenant_id OR v_row.canonical_course_id IS DISTINCT FROM p_course_id OR v_row.course_id IS NOT NULL\n      OR v_row.teacher_party_id<>p_teacher_party_id OR v_row.canonical_teacher_confirmation_id IS DISTINCT FROM p_confirmation_id\n      OR v_row.role<>p_role OR v_row.academic_year<>p_academic_year OR v_row.created_by IS DISTINCT FROM p_actor_id\n      OR v_row.effective_start_date<>p_effective_start_date OR v_row.effective_end_date IS DISTINCT FROM p_effective_end_date\n      OR v_row.status<>'active'\n    THEN RAISE EXCEPTION 'PRESCHOOL_TEACHER_OPERATION_CONFLICT' USING ERRCODE='23505'; END IF;\n    -- Retain immutable tenant/Party/branch proof binding without demanding that\n    -- the confirmation still grants new-assignment eligibility at replay time.\n    PERFORM 1 FROM public.preschool_teacher_branch_confirmations\n      WHERE id=p_confirmation_id AND tenant_id=p_tenant_id AND branch_id=p_branch_id\n        AND teacher_party_id=p_teacher_party_id FOR SHARE;\n    IF NOT FOUND THEN RAISE EXCEPTION 'PRESCHOOL_TEACHER_CONFIRMATION_DENIED' USING ERRCODE='42501'; END IF;\n    PERFORM public.preschool_teacher_assert_admin(p_tenant_id,p_actor_id,p_branch_id,p_course_id);\n    RETURN to_jsonb(v_row);\n  END IF;\n  SELECT * INTO v_confirmation FROM public.preschool_teacher_branch_confirmations\n    WHERE id=p_confirmation_id AND tenant_id=p_tenant_id AND branch_id=p_branch_id AND teacher_party_id=p_teacher_party_id FOR SHARE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'PRESCHOOL_TEACHER_CONFIRMATION_DENIED' USING ERRCODE='42501'; END IF;\n  IF v_confirmation.revoked_at IS NOT NULL OR p_effective_start_date<v_confirmation.valid_from\n    OR (v_confirmation.valid_to IS NOT NULL AND (p_effective_end_date IS NULL OR p_effective_end_date>v_confirmation.valid_to))\n  THEN RAISE EXCEPTION 'PRESCHOOL_TEACHER_CONFIRMATION_DENIED' USING ERRCODE='42501'; END IF;\n  PERFORM 1 FROM public.party_parties p WHERE p.id=p_teacher_party_id AND p.tenant_id=p_tenant_id\n    AND p.party_type='person' AND p.deleted_at IS NULL AND btrim(p.display_name)<>'' FOR SHARE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'PRESCHOOL_TEACHER_PARTY_DENIED' USING ERRCODE='42501'; END IF;\n  IF NOT EXISTS (SELECT 1 FROM public.edu_courses WHERE id=p_course_id AND tenant_id=p_tenant_id AND status='active')\n  THEN RAISE EXCEPTION 'PRESCHOOL_TEACHER_COURSE_DENIED' USING ERRCODE='42501'; END IF;\n  INSERT INTO public.teacher_assignments(assignment_id,tenant_id,course_id,canonical_course_id,teacher_party_id,\n    canonical_teacher_confirmation_id,role,academic_year,effective_start_date,effective_end_date,status,created_by,updated_by)\n    VALUES(p_operation_key,p_tenant_id,NULL,p_course_id,p_teacher_party_id,p_confirmation_id,p_role,p_academic_year,\n      p_effective_start_date,p_effective_end_date,'active',p_actor_id,p_actor_id) RETURNING * INTO v_row;\n  PERFORM public.preschool_teacher_assert_admin(p_tenant_id,p_actor_id,p_branch_id,p_course_id);\n  -- Confirmation/Party rows are SHARE-locked through commit, including any unique-index wait.\n  RETURN to_jsonb(v_row);\nEND $function$\n",
            "securityDefiner": true
        },
        {
            "acl": "{postgres=X/postgres,service_role=X/postgres}",
            "owner": "postgres",
            "config": [
                "search_path=\"\"",
                "statement_timeout=10s",
                "lock_timeout=2s"
            ],
            "signature": "edu_get_preschool_course_teachers(uuid,uuid,uuid,uuid,date,integer,integer)",
            "definition": "CREATE OR REPLACE FUNCTION public.edu_get_preschool_course_teachers(p_tenant_id uuid, p_actor_id uuid, p_branch_id uuid, p_course_id uuid, p_on_date date, p_offset integer DEFAULT 0, p_limit integer DEFAULT 20)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\n SET statement_timeout TO '10s'\n SET lock_timeout TO '2s'\nAS $function$\nDECLARE v_result jsonb;\nBEGIN\n  PERFORM public.preschool_teacher_assert_admin(p_tenant_id,p_actor_id,p_branch_id,p_course_id);\n  IF p_course_id IS NULL OR p_on_date IS NULL OR NOT isfinite(p_on_date)\n    OR p_offset IS NULL OR p_offset<0 OR p_offset>100000 OR p_limit IS NULL OR p_limit<1 OR p_limit>50\n  THEN RAISE EXCEPTION 'PRESCHOOL_TEACHER_INVALID_REQUEST' USING ERRCODE='22023'; END IF;\n  -- A remap/mismatched proof must not masquerade as an empty valid roster.\n  IF EXISTS (SELECT 1 FROM public.teacher_assignments a\n    LEFT JOIN public.preschool_teacher_branch_confirmations c ON c.id=a.canonical_teacher_confirmation_id\n    WHERE a.tenant_id=p_tenant_id AND a.canonical_course_id=p_course_id\n      AND (c.id IS NULL OR c.tenant_id<>a.tenant_id OR c.branch_id<>p_branch_id OR c.teacher_party_id<>a.teacher_party_id))\n  THEN RAISE EXCEPTION 'PRESCHOOL_TEACHER_CONFIGURATION_UNAVAILABLE' USING ERRCODE='55000'; END IF;\n  WITH assignments AS (\n    SELECT a.assignment_id,to_jsonb(a)||jsonb_build_object('branchId',p_branch_id,\n      'teacherName',CASE WHEN p.party_type='person' AND p.deleted_at IS NULL\n        AND coalesce(btrim(p.display_name),'')<>'' THEN p.display_name ELSE NULL END,\n      'effectiveOnDate',a.status='active' AND a.effective_start_date<=p_on_date\n        AND (a.effective_end_date IS NULL OR a.effective_end_date>=p_on_date),\n      'eligibility',CASE WHEN p.id IS NULL OR p.party_type<>'person' OR p.deleted_at IS NOT NULL\n        OR coalesce(btrim(p.display_name),'')='' THEN 'identity_unavailable'\n        WHEN c.revoked_at IS NOT NULL THEN 'confirmation_revoked'\n        WHEN c.valid_from>p_on_date OR (c.valid_to IS NOT NULL AND c.valid_to<p_on_date) THEN 'outside_confirmation_dates'\n        ELSE 'confirmed' END) data\n    FROM public.teacher_assignments a JOIN public.preschool_teacher_branch_confirmations c ON c.id=a.canonical_teacher_confirmation_id\n    LEFT JOIN public.party_parties p ON p.id=a.teacher_party_id AND p.tenant_id=a.tenant_id\n    WHERE a.tenant_id=p_tenant_id AND a.canonical_course_id=p_course_id AND a.course_id IS NULL\n  ), page AS (SELECT * FROM assignments ORDER BY assignment_id OFFSET p_offset LIMIT p_limit)\n  SELECT jsonb_build_object('tenantId',p_tenant_id,'branchId',p_branch_id,'courseId',p_course_id,'onDate',p_on_date,\n    'offset',p_offset,'limit',p_limit,'total',(SELECT count(*) FROM assignments),\n    'nextOffset',CASE WHEN p_offset::bigint+p_limit<(SELECT count(*) FROM assignments) AND p_offset+p_limit<=100000\n      THEN p_offset+p_limit ELSE NULL END,\n    'assignments',(SELECT coalesce(jsonb_agg(data ORDER BY assignment_id),'[]'::jsonb) FROM page)) INTO v_result;\n  PERFORM public.preschool_teacher_assert_admin(p_tenant_id,p_actor_id,p_branch_id,p_course_id);\n  RETURN v_result;\nEND $function$\n",
            "securityDefiner": true
        },
        {
            "acl": "{=X/postgres,postgres=X/postgres,service_role=X/postgres,bella_migration_executor=X/postgres}",
            "owner": "postgres",
            "config": [
                "search_path=pg_catalog, public"
            ],
            "signature": "get_auth_tenant_id()",
            "definition": "CREATE OR REPLACE FUNCTION public.get_auth_tenant_id()\n RETURNS uuid\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nDECLARE\n  v_tenant_id uuid;\nBEGIN\n  SELECT u.tenant_id INTO v_tenant_id\n  FROM public.users AS u\n  JOIN public.tenants AS t ON t.id = u.tenant_id\n  WHERE u.id = auth.uid() AND u.status = 'active' AND t.status = 'active';\n\n  -- NULL would enable legacy policies using NULL as an unrestricted HQ sentinel.\n  IF v_tenant_id IS NULL THEN\n    RAISE EXCEPTION 'Active canonical identity and tenant required' USING ERRCODE = '42501';\n  END IF;\n  RETURN v_tenant_id;\nEND;\n$function$\n",
            "securityDefiner": true
        },
        {
            "acl": "{postgres=X/postgres,authenticated=X/postgres}",
            "owner": "postgres",
            "config": [
                "search_path=pg_catalog"
            ],
            "signature": "party_resolve_current_auth_link()",
            "definition": "CREATE OR REPLACE FUNCTION public.party_resolve_current_auth_link()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog'\nAS $function$\nDECLARE c record; r public.party_auth_links%ROWTYPE;\nBEGIN\n  SELECT * INTO c FROM public.party_auth_link_context(false,false);\n  SELECT l.* INTO r FROM public.party_auth_links l JOIN public.party_parties p ON p.id=l.party_id AND p.tenant_id=l.tenant_id\n    WHERE l.auth_user_id=c.actor_id AND l.tenant_id=c.tenant_id AND l.revoked_at IS NULL\n      AND l.valid_from<=clock_timestamp() AND (l.valid_until IS NULL OR l.valid_until>clock_timestamp())\n      AND p.party_type='person' AND p.deleted_at IS NULL AND btrim(p.display_name)<>'';\n  IF NOT FOUND THEN RETURN NULL; END IF;\n  RETURN jsonb_build_object('id',r.id,'tenantId',r.tenant_id,'authUserId',r.auth_user_id,\n    'partyId',r.party_id,'validFrom',r.valid_from,'validUntil',r.valid_until);\nEND;\n$function$\n",
            "securityDefiner": true
        },
        {
            "acl": "{postgres=X/postgres,service_role=X/postgres}",
            "owner": "postgres",
            "config": [
                "search_path=\"\""
            ],
            "signature": "platform_assert_active_branch_for_actor(uuid,uuid,uuid)",
            "definition": "CREATE OR REPLACE FUNCTION public.platform_assert_active_branch_for_actor(p_tenant_id uuid, p_actor_id uuid, p_branch_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\nBEGIN\r\n  IF auth.role() IS DISTINCT FROM 'service_role' OR p_tenant_id IS NULL OR p_actor_id IS NULL OR p_branch_id IS NULL\r\n    OR (auth.uid() IS NOT NULL AND auth.uid() IS DISTINCT FROM p_actor_id) THEN\r\n    RAISE EXCEPTION 'PLATFORM_BRANCH_ACTOR_DENIED' USING ERRCODE='42501';\r\n  END IF;\r\n  PERFORM 1 FROM public.org_units ou WHERE ou.id=p_branch_id AND ou.tenant_id=p_tenant_id\r\n    AND ou.unit_type='branch' AND ou.is_active=true FOR SHARE;\r\n  IF NOT FOUND THEN RAISE EXCEPTION 'PLATFORM_ACTIVE_BRANCH_REQUIRED' USING ERRCODE='42501'; END IF;\r\n  IF NOT EXISTS(SELECT 1 FROM public.platform_org_unit_access_for_actor(p_tenant_id,p_actor_id) a\r\n    WHERE a.user_id=p_actor_id AND a.tenant_id=p_tenant_id AND a.org_unit_id=p_branch_id\r\n      AND a.relationship_id IS NOT NULL AND a.access_source IN ('belongs_to','manages','participates_in')) THEN\r\n    RAISE EXCEPTION 'PLATFORM_EXPLICIT_BRANCH_ACCESS_DENIED' USING ERRCODE='42501';\r\n  END IF;\r\nEND;\r\n$function$\n",
            "securityDefiner": true
        },
        {
            "acl": "{postgres=X/postgres,authenticated=X/postgres}",
            "owner": "postgres",
            "config": [
                "search_path=\"\""
            ],
            "signature": "platform_current_actor_org_unit_access()",
            "definition": "CREATE OR REPLACE FUNCTION public.platform_current_actor_org_unit_access()\n RETURNS TABLE(user_id uuid, tenant_id uuid, org_unit_id uuid, root_org_unit_id uuid, relationship_id uuid, access_source text)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nDECLARE v_tenant_id uuid;\nBEGIN\n  SELECT p.tenant_id INTO v_tenant_id FROM public.platform_current_actor_profile() p;\n  RETURN QUERY\n    SELECT a.user_id, a.tenant_id, a.org_unit_id, a.root_org_unit_id,\n      a.relationship_id, a.access_source\n    FROM public.platform_org_unit_access_for_actor(v_tenant_id, auth.uid()) a;\nEND;\n$function$\n",
            "securityDefiner": true
        },
        {
            "acl": "{postgres=X/postgres,authenticated=X/postgres}",
            "owner": "postgres",
            "config": [
                "search_path=\"\""
            ],
            "signature": "platform_current_actor_profile()",
            "definition": "CREATE OR REPLACE FUNCTION public.platform_current_actor_profile()\n RETURNS TABLE(id uuid, email text, full_name text, role text, avatar_url text, tenant_id uuid, status text, tenant_status text)\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nBEGIN\n  IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' THEN\n    RAISE EXCEPTION 'PLATFORM_CURRENT_ACTOR_DENIED: Signed-in actor required.' USING ERRCODE = '42501';\n  END IF;\n  RETURN QUERY\n    SELECT u.id, u.email::text, u.full_name::text, u.role::text, u.avatar_url::text,\n      u.tenant_id, u.status::text, t.status::text\n    FROM auth.users a\n    JOIN public.users u ON u.id = a.id\n    JOIN public.tenants t ON t.id = u.tenant_id\n    WHERE a.id = auth.uid() AND a.deleted_at IS NULL\n      AND (a.banned_until IS NULL OR a.banned_until <= now())\n      AND u.status = 'active' AND t.status = 'active';\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'PLATFORM_CURRENT_ACTOR_DENIED: Current active identity and tenant required.' USING ERRCODE = '42501';\n  END IF;\nEND;\n$function$\n",
            "securityDefiner": true
        },
        {
            "acl": "{postgres=X/postgres,service_role=X/postgres}",
            "owner": "postgres",
            "config": [
                "search_path=\"\""
            ],
            "signature": "platform_org_unit_access_for_actor(uuid,uuid)",
            "definition": "CREATE OR REPLACE FUNCTION public.platform_org_unit_access_for_actor(p_tenant_id uuid, p_actor_id uuid)\n RETURNS TABLE(user_id uuid, tenant_id uuid, org_unit_id uuid, root_org_unit_id uuid, relationship_id uuid, access_source text)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nBEGIN\n    IF p_tenant_id IS NULL OR p_actor_id IS NULL\n       OR (auth.uid() IS NOT NULL AND auth.uid() IS DISTINCT FROM p_actor_id) THEN\n        RAISE EXCEPTION 'PLATFORM_ACTOR_ACCESS_DENIED: Trusted actor context required.' USING ERRCODE = '42501';\n    END IF;\n\n    PERFORM 1 FROM auth.users a\n      JOIN public.users u ON u.id = a.id\n      JOIN public.tenants t ON t.id = u.tenant_id\n    WHERE a.id = p_actor_id AND a.deleted_at IS NULL\n      AND (a.banned_until IS NULL OR a.banned_until <= now())\n      AND u.tenant_id = p_tenant_id AND u.status = 'active' AND t.status = 'active';\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'PLATFORM_ACTOR_ACCESS_DENIED: Current active Auth-backed actor and tenant required.' USING ERRCODE = '42501';\n    END IF;\n\n    RETURN QUERY\n    WITH RECURSIVE direct_access AS (\n      SELECT pd.user_id, rel.tenant_id, rel.to_id AS org_unit_id,\n        rel.to_id AS root_org_unit_id, rel.id AS relationship_id,\n        rel.rel_type AS access_source\n      FROM public.people_directory pd\n      JOIN public.org_relationships rel ON rel.tenant_id = pd.tenant_id\n        AND rel.from_id = pd.id AND rel.from_type = 'person' AND rel.to_type = 'unit'\n        AND rel.rel_type IN ('belongs_to', 'manages', 'participates_in')\n        AND (rel.since IS NULL OR rel.since <= CURRENT_DATE)\n        AND (rel.until IS NULL OR rel.until >= CURRENT_DATE)\n      JOIN public.org_units ou ON ou.id = rel.to_id\n        AND ou.tenant_id = rel.tenant_id AND ou.is_active = TRUE\n      WHERE pd.user_id = p_actor_id AND pd.tenant_id = p_tenant_id AND pd.is_active = TRUE\n    ), expanded_access AS (\n      SELECT da.user_id, da.tenant_id, da.org_unit_id, da.root_org_unit_id,\n        da.relationship_id, da.access_source FROM direct_access da\n      UNION\n      SELECT ea.user_id, child.tenant_id, child.id, ea.root_org_unit_id,\n        ea.relationship_id, ea.access_source\n      FROM expanded_access ea\n      JOIN public.org_units child ON child.parent_id = ea.org_unit_id\n        AND child.tenant_id = ea.tenant_id AND child.is_active = TRUE\n    ), admin_access AS (\n      SELECT u.id AS user_id, ou.tenant_id, ou.id AS org_unit_id,\n        ou.id AS root_org_unit_id, NULL::uuid AS relationship_id,\n        'tenant_admin'::text AS access_source\n      FROM public.users u\n      JOIN public.org_units ou ON ou.tenant_id = u.tenant_id AND ou.is_active = TRUE\n      WHERE u.id = p_actor_id AND u.tenant_id = p_tenant_id\n        AND lower(u.role) IN ('admin', 'super_admin')\n    )\n    SELECT ea.user_id, ea.tenant_id, ea.org_unit_id, ea.root_org_unit_id,\n      ea.relationship_id, ea.access_source FROM expanded_access ea\n    UNION\n    SELECT aa.user_id, aa.tenant_id, aa.org_unit_id, aa.root_org_unit_id,\n      aa.relationship_id, aa.access_source FROM admin_access aa;\nEND;\n$function$\n",
            "securityDefiner": true
        },
        {
