            "type": "c",
            "relation": "teacher_assignments",
            "validated": true,
            "definition": "CHECK (role = ANY (ARRAY['lead_teacher'::text, 'co_teacher'::text, 'assistant'::text, 'substitute'::text]))"
        },
        {
            "name": "teacher_assignments_status_check",
            "type": "c",
            "relation": "teacher_assignments",
            "validated": true,
            "definition": "CHECK (status = ANY (ARRAY['active'::text, 'completed'::text, 'terminated'::text]))"
        },
        {
            "name": "teacher_assignments_teacher_fk",
            "type": "f",
            "relation": "teacher_assignments",
            "validated": true,
            "definition": "FOREIGN KEY (teacher_party_id) REFERENCES party_parties(id) ON DELETE RESTRICT"
        },
        {
            "name": "teacher_assignments_tenant_fk",
            "type": "f",
            "relation": "teacher_assignments",
            "validated": true,
            "definition": "FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE"
        },
        {
            "name": "tenants_accounting_mode_check",
            "type": "c",
            "relation": "tenants",
            "validated": true,
            "definition": "CHECK (accounting_mode = ANY (ARRAY['SIMPLE'::text, 'PROFESSIONAL'::text]))"
        },
        {
            "name": "tenants_parent_tenant_id_fkey",
            "type": "f",
            "relation": "tenants",
            "validated": true,
            "definition": "FOREIGN KEY (parent_tenant_id) REFERENCES tenants(id)"
        },
        {
            "name": "tenants_pkey",
            "type": "p",
            "relation": "tenants",
            "validated": true,
            "definition": "PRIMARY KEY (id)"
        },
        {
            "name": "tenants_royalty_type_check",
            "type": "c",
            "relation": "tenants",
            "validated": true,
            "definition": "CHECK (royalty_type::text = ANY (ARRAY['fixed'::character varying, 'percentage'::character varying]::text[]))"
        },
        {
            "name": "tenants_status_check",
            "type": "c",
            "relation": "tenants",
