        {
            "name": "users_pkey",
            "type": "p",
            "relation": "users",
            "validated": true,
            "definition": "PRIMARY KEY (id)"
        },
        {
            "name": "users_position_tier_check",
            "type": "c",
            "relation": "users",
            "validated": true,
            "definition": "CHECK (position_tier = ANY (ARRAY['junior'::text, 'senior'::text, 'lead'::text]))"
