        {
            "name": "users_role_check",
            "type": "c",
            "relation": "users",
            "validated": true,
            "definition": "CHECK (role = ANY (ARRAY['admin'::text, 'ktv_lead'::text, 'ktv'::text, 'admin_staff'::text, 'accountant'::text, 'hr'::text, 'student'::text, 'parent'::text]))"
        },
